-- Startkatalog (generiert von scripts/gen-catalog-sql.mjs – nicht von Hand ändern)
-- Nach 0001_init.sql im SQL Editor ausführen. Erneutes Ausführen aktualisiert nur Katalogzeilen.
on conflict (id) do update set name = excluded.name
  where public.manufacturers.created_by is null;

on conflict (id) do update set name = excluded.name, type = excluded.type, muscle_group = excluded.muscle_group, split = excluded.split, free_weight = excluded.free_weight
  where public.exercises.created_by is null;

on conflict (id) do update set manufacturer_id = excluded.manufacturer_id, name = excluded.name, line = excluded.line, kind = excluded.kind, exercise_id = excluded.exercise_id, weight_step_kg = excluded.weight_step_kg
  where public.equipment_models.created_by is null;
